/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: release, candidate, durationsOf, filesFrom
 *   Constants: guard, releases, noIdentifiers, hotelCalifornia, hotelBase, jitter
 * Tests
 *   - Hotel California: every 9-track edition within tolerance matches, groups split by first label and longer or shorter editions do not match
 *   - Hotel California: a barcode shared by several matching editions preselects nothing, the release-ID tag preselects exactly that edition
 *   - Blue Archive: the JP CD and JP digital editions match as two groups and the Korean edition is excluded by two disclosed deltas
 *   - Pandora Call: only the two 1-track singles match, as one group represented by the single with front artwork
 *   - an unknown local duration is unverified, disclosed and never preselected
 *   - an incomplete candidate is last, unranked and never preselected, even when its ID equals the tag
 *   - unknown disc numbers are disclosed while the candidate still matches; a known disc count must agree
 *   - a medium without tracks is not a disc: the comparison and the proposal number discs among media that have tracks
 *   - ranking is identical under any permutation and the representative prefers front artwork
 *   - artist mismatch compares case-folded NFC tags with the joined credit, credited names and canonical names
 *   - the tolerance boundary is the tolerance plus the local precision, and legacy durations carry one-second precision
 *   - proposals keep credited names and join phrases, mark featured entries and never propose placeholders
 *   - newly known durations re-rank the stored candidates without any request
 *   - matching groups come first by representative key, then other candidates by track-count gap, disc-count gap and summed duration gap
 *   - a fetched release with another ID is incomplete, and a duplicate key keeps its complete entry in either order
 *   - a shared catalogue number preselects case-insensitively, and an identifier rule without exactly one matching hit falls through
 *   - an unverified candidate is never preselected, even by its own release ID
 * @end-catalog */

import assert from 'node:assert/strict';
import { readdirSync } from 'node:fs';
import path from 'node:path';
import { after, test } from 'node:test';
import type { MusicBrainzRelease } from '../../src/administration/lookup/lookupContract';
import {
    legacyDurationEvidence, proposalForRelease, rankLookupCandidates, type LocalFileEvidence, type LookupCandidate
} from '../../src/administration/lookup/lookupRanking';
import { parseMusicBrainzRelease } from '../../src/administration/lookup/musicBrainzClient';
import { fixtureRoot, loadLookupFixture } from '../support/metadataLookupFixtures';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

/** Every recorded MusicBrainz release, parsed by the production parser. */
const releases = new Map<string, MusicBrainzRelease>(readdirSync(path.join(fixtureRoot, 'musicbrainz'))
    .filter(name => /^release-[0-9a-f-]{36}\.json$/.test(name))
    .map(name => parseMusicBrainzRelease(loadLookupFixture(`musicbrainz/${name}`).exchanges.at(-1)!.body))
    .map(release => [release.releaseId, release]));
const release = (prefix: string) => [...releases.values()].find(candidate => candidate.releaseId.startsWith(prefix))!;
const candidate = (value: MusicBrainzRelease, complete = true): LookupCandidate =>
    ({ key: `musicbrainz:${value.releaseId}`, source: 'musicbrainz', releaseId: value.releaseId, summary: null, release: complete ? value : null });
const durationsOf = (value: MusicBrainzRelease) => value.media.flatMap(medium => medium.tracks.map(track => track.lengthMs));
const noIdentifiers = { releaseId: null, barcode: null, catalogNumber: null };
const filesFrom = (value: MusicBrainzRelease, options: { jitter?: number[]; discs?: boolean; artistTags?: string[]; identifiers?: Partial<LocalFileEvidence['identifiers']> } = {}): LocalFileEvidence[] =>
    value.media.flatMap(medium => medium.tracks.map(track => ({ medium, track }))).map(({ medium, track }, index) => ({
        slotId: `slot-${String(index).padStart(2, '0')}`, order: index, durationMs: track.lengthMs! + (options.jitter?.[index % options.jitter.length] ?? 0),
        durationPrecisionMs: 0, discNumber: options.discs ? medium.position : null, trackNumber: track.position,
        artistTags: options.artistTags ?? [], identifiers: { ...noIdentifiers, ...options.identifiers }
    }));

const hotelCalifornia = [...releases.values()].filter(value => value.title === 'Hotel California');
const hotelBase = release('24ae881f');
const jitter = [800, -800, 800, -800, 800, -800, 800, -800, 800];

test('Hotel California: every 9-track edition within tolerance matches, groups split by first label and longer or shorter editions do not match', () => {
    const files = filesFrom(hotelBase, { jitter, artistTags: ['Eagles'] });
    const ranked = rankLookupCandidates(hotelCalifornia.map(value => candidate(value)), files);
    const expected = hotelCalifornia.filter(value => {
        const durations = durationsOf(value);
        return durations.length === 9 && durations.every((duration, index) => duration !== null && Math.abs(files[index].durationMs! - duration) <= 3000);
    }).map(value => value.releaseId).sort();
    const matching = ranked.candidates.filter(entry => entry.status === 'matching');
    assert.deepEqual(matching.map(entry => entry.releaseId).sort(), expected);
    assert.ok(expected.length >= 10);
    for (const prefix of ['24ae881f', '0a9833a9', 'e38dc685', 'bef9ebe8', '519c3c07']) assert.ok(expected.some(id => id.startsWith(prefix)), prefix);
    for (const prefix of ['7b73e57c', 'ebd981c7', '54614efa', '0ea3b00b']) {
        const remaster = ranked.candidates.find(entry => entry.releaseId.startsWith(prefix))!;
        assert.equal(remaster.status, 'notMatching', prefix); assert.deepEqual(remaster.comparison!.differences, ['duration']);
    }
    // One group per first label: Asylum, Elektra, DCC, Mobile Fidelity and Warner Bros.
    const labels = ranked.groups.map(group => group.proposal.label).sort();
    assert.deepEqual(labels, ['Asylum Records', 'DCC Compact Classics', 'Elektra', 'Mobile Fidelity Sound Lab', 'Warner Bros. Records']);
    for (const group of ranked.groups) {
        for (const key of group.memberKeys) assert.equal(proposalForRelease(release(key.slice(12))).label, group.proposal.label);
    }
    assert.ok(ranked.groups.find(group => group.proposal.label === 'Asylum Records')!.memberKeys.length > 1);
    for (const [prefix, tracks] of [['bb82e6d7', 19], ['1c0f39f3', 19], ['b42f7f38', 27], ['14a2a203', 18], ['f72b3971', 12], ['1e166986', 1]] as const) {
        const longer = ranked.candidates.find(entry => entry.releaseId.startsWith(prefix))!;
        assert.equal(longer.status, 'notMatching', prefix); assert.equal(longer.comparison!.trackCount.candidate, tracks, prefix);
        assert.ok(longer.comparison!.differences.includes('trackCount'));
    }
    assert.equal(ranked.preselection, null, 'several matching groups and no identifier preselect nothing');
    assert.ok(matching.every(entry => entry.artistMismatch === false));
    // Observed deviation of every matching edition from the 24ae881f durations: at most 2200 ms.
    const deviation = Math.max(...matching.map(entry => Math.max(...durationsOf(release(entry.releaseId)).map((duration, index) => Math.abs(duration! - durationsOf(hotelBase)[index]!)))));
    assert.equal(deviation, 2200);
});

test('Hotel California: a barcode shared by several matching editions preselects nothing, the release-ID tag preselects exactly that edition', () => {
    const shared = rankLookupCandidates(hotelCalifornia.map(value => candidate(value)), filesFrom(hotelBase, { jitter, identifiers: { barcode: '075596050920' } }));
    const carriers = shared.candidates.filter(entry => entry.status === 'matching' && ['24ae881f', '304a548c', '3f223a88', '519c3c07'].some(prefix => entry.releaseId.startsWith(prefix)));
    assert.equal(carriers.length, 4, 'GTIN-14 comparison also matches the 0075596050920 Warner barcode');
    assert.equal(shared.preselection, null);
    const tagged = rankLookupCandidates(hotelCalifornia.map(value => candidate(value)),
        filesFrom(hotelBase, { jitter, identifiers: { releaseId: hotelBase.releaseId.toUpperCase() } }));
    assert.deepEqual(tagged.preselection, { candidateKey: `musicbrainz:${hotelBase.releaseId}`,
        groupKey: tagged.candidates.find(entry => entry.releaseId === hotelBase.releaseId)!.groupKey, basis: 'releaseId', artistMismatch: false });
});

test('Blue Archive: the JP CD and JP digital editions match as two groups and the Korean edition is excluded by two disclosed deltas', () => {
    const cd = release('8baecda4'), digital = release('8f032fff'), korean = release('85bc0ffc');
    const files = filesFrom(cd, { discs: true, artistTags: ['Mitsukiyo、KARUT、Nor'] });
    assert.equal(files.length, 39);
    const ranked = rankLookupCandidates([candidate(korean), candidate(digital), candidate(cd)], files);
    const status = Object.fromEntries(ranked.candidates.map(entry => [entry.releaseId.slice(0, 8), entry.status]));
    assert.deepEqual(status, { '8baecda4': 'matching', '8f032fff': 'matching', '85bc0ffc': 'notMatching' });
    assert.equal(ranked.groups.length, 2); assert.equal(ranked.preselection, null);
    const excluded = ranked.candidates.find(entry => entry.releaseId === korean.releaseId)!.comparison!;
    assert.deepEqual(excluded.differences, ['duration']);
    assert.deepEqual(excluded.discCount, { local: 2, candidate: 2 });
    const over = excluded.files.filter(file => file.withinTolerance === false);
    assert.deepEqual(over.map(file => file.deltaMs), [19054, 9627]);
    // Apart from those two tracks, the Korean edition stays within the tolerance; its largest deviation is exactly 3000 ms.
    assert.equal(Math.max(...excluded.files.filter(file => file.withinTolerance).map(file => Math.abs(file.deltaMs!))), 3000);
    const barcode = rankLookupCandidates([candidate(korean), candidate(digital), candidate(cd)], filesFrom(cd, { discs: true, identifiers: { barcode: '4582579942951' } }));
    assert.equal(barcode.preselection?.candidateKey, `musicbrainz:${cd.releaseId}`); assert.equal(barcode.preselection?.basis, 'barcode');
});

test('Pandora Call: only the two 1-track singles match, as one group represented by the single with front artwork', () => {
    const pandora = [...releases.values()].filter(value => value.media.some(medium => medium.tracks.some(track => track.title === 'パンドラコール')));
    assert.deepEqual(pandora.map(value => value.trackCount).sort((left, right) => left - right), [1, 1, 15, 15, 15, 15, 25, 50]);
    const files: LocalFileEvidence[] = [{ slotId: 'only', order: 0, durationMs: 217_000, durationPrecisionMs: 0, discNumber: null, trackNumber: null,
        artistTags: ['ヰ世界情緒'], identifiers: noIdentifiers }];
    const ranked = rankLookupCandidates(pandora.map(value => candidate(value)), files);
    const matching = ranked.candidates.filter(entry => entry.status === 'matching').map(entry => entry.releaseId.slice(0, 8)).sort();
    assert.deepEqual(matching, ['5302459e', '8659aff4']);
    for (const entry of ranked.candidates.filter(item => item.status !== 'matching')) assert.ok([15, 25, 50].includes(entry.comparison!.trackCount.candidate));
    assert.equal(ranked.groups.length, 1); assert.equal(ranked.groups[0].memberKeys.length, 2);
    assert.equal(release('5302459e').frontArtwork, true); assert.equal(release('8659aff4').frontArtwork, false);
    assert.deepEqual(ranked.preselection, { candidateKey: `musicbrainz:${release('5302459e').releaseId}`, groupKey: ranked.groups[0].groupKey,
        basis: 'onlyMatchingGroup', artistMismatch: false });
    assert.deepEqual(ranked.candidates.slice(0, 2).map(entry => entry.releaseId.slice(0, 8)), ['5302459e', '8659aff4']);
});

test('an unknown local duration is unverified, disclosed and never preselected', () => {
    const files = filesFrom(release('5302459e')).map(file => ({ ...file, durationMs: null }));
    const ranked = rankLookupCandidates([candidate(release('5302459e'))], files);
    assert.equal(ranked.candidates[0].status, 'unverified'); assert.equal(ranked.candidates[0].comparison!.unknownLocalDurations, 1);
    assert.deepEqual(ranked.disclosure, { unknownLocalDurations: 1, unknownLocalDiscNumbers: 1 });
    assert.equal(ranked.preselection, null); assert.deepEqual(ranked.groups, []);
    const unknownRemote = structuredClone(release('5302459e'));
    unknownRemote.media[0].tracks[0].lengthMs = null;
    const remote = rankLookupCandidates([candidate(unknownRemote)], filesFrom(release('5302459e')));
    assert.equal(remote.candidates[0].status, 'unverified'); assert.equal(remote.candidates[0].comparison!.unknownCandidateDurations, 1);
});

test('an incomplete candidate is last, unranked and never preselected, even when its ID equals the tag', () => {
    const files = filesFrom(hotelBase, { identifiers: { releaseId: hotelBase.releaseId } });
    const ranked = rankLookupCandidates([candidate(hotelBase, false), candidate(release('0a9833a9'))], files);
    assert.equal(ranked.candidates.at(-1)!.releaseId, hotelBase.releaseId);
    assert.equal(ranked.candidates.at(-1)!.status, 'incomplete'); assert.equal(ranked.candidates.at(-1)!.comparison, null);
    assert.equal(ranked.preselection?.candidateKey, `musicbrainz:${release('0a9833a9').releaseId}`);
    assert.equal(ranked.preselection?.basis, 'onlyMatchingGroup');
    const alone = rankLookupCandidates([candidate(hotelBase, false)], files);
    assert.equal(alone.preselection, null);
});

test('unknown disc numbers are disclosed while the candidate still matches; a known disc count must agree', () => {
    const cd = release('8baecda4');
    // Track Numbers restart on disc 2, so without Disc Numbers the upload order assigns the tracks.
    const withoutDiscs = rankLookupCandidates([candidate(cd)], [...filesFrom(cd)].reverse());
    assert.equal(withoutDiscs.candidates[0].status, 'matching'); assert.equal(withoutDiscs.disclosure.unknownLocalDiscNumbers, 39);
    assert.equal(withoutDiscs.candidates[0].comparison!.discCount.local, null);
    const oneDisc = filesFrom(cd, { discs: true }).map(file => ({ ...file, discNumber: 1 }));
    const wrong = rankLookupCandidates([candidate(cd)], oneDisc);
    assert.equal(wrong.candidates[0].status, 'notMatching'); assert.ok(wrong.candidates[0].comparison!.differences.includes('discCount'));
});

test('a medium without tracks is not a disc: the comparison and the proposal number discs among media that have tracks', () => {
    const base = structuredClone(hotelBase);
    const withDvd: MusicBrainzRelease = { ...base, media: [{ position: 1, format: 'DVD', tracks: [] }, { ...base.media[0], position: 2 }] };
    const files = filesFrom(hotelBase, { discs: true });
    assert.ok(files.every(file => file.discNumber === 1));
    const ranked = rankLookupCandidates([candidate(withDvd)], files);
    assert.equal(ranked.candidates[0].status, 'matching');
    assert.deepEqual(ranked.candidates[0].comparison!.discCount, { local: 1, candidate: 1 });
    const proposal = proposalForRelease(withDvd);
    assert.equal(proposal.tracks.length, 9);
    assert.ok(proposal.tracks.every(track => track.discNumber === 1), 'the CD after a DVD without a tracklist is Disc Number 1');
    const twoDiscs = proposalForRelease(release('8baecda4'));
    assert.deepEqual([...new Set(twoDiscs.tracks.map(track => track.discNumber))], [1, 2]);
});

test('ranking is identical under any permutation and the representative prefers front artwork', () => {
    const files = filesFrom(hotelBase, { jitter, artistTags: ['Eagles'] });
    const input = hotelCalifornia.map(value => candidate(value));
    const expected = rankLookupCandidates(input, files);
    for (let seed = 1; seed <= 5; seed++) {
        const shuffled = [...input].sort((left, right) => ((left.releaseId.charCodeAt(seed) * 31 + seed) % 17) - ((right.releaseId.charCodeAt(seed) * 31 + seed) % 17));
        const reversedFiles = [...files].reverse();
        assert.deepEqual(rankLookupCandidates([...shuffled, ...shuffled.slice(0, 3)], reversedFiles), expected);
    }
    const asylum = expected.groups.find(group => group.proposal.label === 'Asylum Records')!;
    const representative = release(asylum.representativeKey.slice(12));
    assert.equal(representative.frontArtwork, true);
    const front = asylum.memberKeys.map(key => release(key.slice(12))).filter(value => value.frontArtwork === true).map(value => value.releaseId).sort();
    assert.equal(representative.releaseId, front[0]);
});

test('artist mismatch compares case-folded NFC tags with the joined credit, credited names and canonical names', () => {
    const cd = release('8baecda4');
    const flag = (artistTags: string[]) => rankLookupCandidates([candidate(cd)], filesFrom(cd, { discs: true, artistTags })).preselection!.artistMismatch;
    assert.equal(flag(['Mitsukiyo、KARUT、Nor']), false);
    assert.equal(flag(['mitsukiyo']), false);
    assert.equal(flag(['ミツキヨ']), false);
    assert.equal(flag(['  KARUT ']), false);
    assert.equal(flag(['ミツキヨ'.normalize('NFD')]), false);
    assert.equal(flag([]), false); assert.equal(flag(['']), false);
    assert.equal(flag(['Someone Else']), true);
    assert.equal(flag(['Someone Else', 'Nor']), false);
});

test('the tolerance boundary is the tolerance plus the local precision, and legacy durations carry one-second precision', () => {
    const single = release('5302459e');
    const remote = single.media[0].tracks[0].lengthMs!;
    const status = (delta: number, durationPrecisionMs: 0 | 1000 = 0) => rankLookupCandidates([candidate(single)],
        [{ slotId: 'only', order: 0, durationMs: remote + delta, durationPrecisionMs, discNumber: null, trackNumber: 1, artistTags: [], identifiers: noIdentifiers }]).candidates[0].status;
    assert.equal(status(3000), 'matching'); assert.equal(status(-3000), 'matching'); assert.equal(status(3001), 'notMatching');
    assert.equal(status(4000, 1000), 'matching'); assert.equal(status(-4001, 1000), 'notMatching');
    assert.deepEqual(legacyDurationEvidence('3:37'), { durationMs: 217_000, durationPrecisionMs: 1000 });
    assert.deepEqual(legacyDurationEvidence('1:02:03'), { durationMs: 3_723_000, durationPrecisionMs: 1000 });
    for (const value of ['', '0:00', '3:7', '3:60', '61:00:00x', 217, null, '1:60:00']) assert.equal(legacyDurationEvidence(value), null, String(value));
});

test('proposals keep credited names and join phrases, mark featured entries and never propose placeholders', () => {
    const cd = proposalForRelease(release('8baecda4'));
    assert.deepEqual(cd.artists, [{ name: 'Mitsukiyo', role: 'primary', joinPhrase: '、' }, { name: 'KARUT', role: 'primary', joinPhrase: '、' },
        { name: 'Nor', role: 'primary', joinPhrase: null }]);
    assert.equal(cd.label, '株式会社Yostar'); assert.deepEqual(cd.releaseDate, { year: 2022, month: 3, day: 24 });
    assert.equal(cd.tracks.length, 39); assert.deepEqual(cd.tracks[20], { discNumber: 2, trackNumber: 1, title: release('8baecda4').media[1].tracks[0].title });
    assert.equal(proposalForRelease(release('0ea3b00b')).label, null, '[no label] is never proposed');
    const featuring = structuredClone(release('5302459e'));
    featuring.artistCredit = [
        { name: 'Lead', joinPhrase: ' feat. ', artistId: '00000000-0000-4000-8000-000000000001', artistName: 'Lead' },
        { name: 'Guest', joinPhrase: ' & ', artistId: '00000000-0000-4000-8000-000000000002', artistName: 'Guest' },
        { name: 'Various Artists', joinPhrase: '', artistId: '89ad4ac3-39f7-470e-963a-56509c546377', artistName: 'Various Artists' }
    ];
    assert.deepEqual(proposalForRelease(featuring).artists, [{ name: 'Lead', role: 'primary', joinPhrase: ' feat. ' }, { name: 'Guest', role: 'featured', joinPhrase: ' & ' }]);
    featuring.artistCredit[0].joinPhrase = ' featuring '; assert.equal(proposalForRelease(featuring).artists[1].role, 'featured');
    featuring.artistCredit[0].joinPhrase = ' (ft. '; assert.equal(proposalForRelease(featuring).artists[1].role, 'featured');
    featuring.artistCredit[0].joinPhrase = ' x '; assert.equal(proposalForRelease(featuring).artists[1].role, 'primary');
    featuring.artistCredit[0].joinPhrase = 'Featherweight'; assert.equal(proposalForRelease(featuring).artists[1].role, 'primary');
});

test('newly known durations re-rank the stored candidates without any request', () => {
    const stored = Object.freeze([candidate(release('5302459e')), candidate(release('4aed7962'))].map(entry => Object.freeze(entry)));
    const unknown: LocalFileEvidence[] = [{ slotId: 'only', order: 0, durationMs: null, durationPrecisionMs: 0, discNumber: null, trackNumber: null, artistTags: [], identifiers: noIdentifiers }];
    const before = rankLookupCandidates(stored, unknown);
    assert.equal(before.candidates.find(entry => entry.releaseId.startsWith('5302459e'))!.status, 'unverified');
    const after = rankLookupCandidates(stored, [{ ...unknown[0], durationMs: 217_100 }]);
    assert.equal(after.candidates.find(entry => entry.releaseId.startsWith('5302459e'))!.status, 'matching');
    assert.equal(after.preselection?.basis, 'onlyMatchingGroup');
    assert.deepEqual(guard.attempts, []);
});

test('matching groups come first by representative key, then other candidates by track-count gap, disc-count gap and summed duration gap', () => {
    const ranked = rankLookupCandidates(hotelCalifornia.map(value => candidate(value)), filesFrom(hotelBase, { jitter }));
    const firstOther = ranked.candidates.findIndex(entry => entry.status !== 'matching');
    assert.ok(firstOther > 0);
    const representatives = ranked.groups.map(group => group.representativeKey);
    assert.deepEqual(representatives, [...representatives].sort());
    assert.deepEqual(ranked.candidates.slice(0, firstOther).map(entry => entry.key), ranked.groups.flatMap(group => group.memberKeys));
    for (const group of ranked.groups) {
        const members = group.memberKeys.map(key => release(key.slice(12)));
        const expected = [...members].sort((left, right) => Number(right.frontArtwork === true) - Number(left.frontArtwork === true)
            || (left.releaseId < right.releaseId ? -1 : 1));
        assert.deepEqual(members.map(member => member.releaseId), expected.map(member => member.releaseId), 'front artwork first, then release ID');
        assert.equal(group.representativeKey, group.memberKeys[0]);
    }
    const others = ranked.candidates.slice(firstOther);
    assert.ok(others.every(entry => entry.status === 'notMatching' || entry.status === 'unverified'));
    const sortKey = (entry: typeof others[number]) => {
        const comparison = entry.comparison!;
        const counted = comparison.trackCount.local === comparison.trackCount.candidate;
        return [Math.abs(comparison.trackCount.local - comparison.trackCount.candidate),
            comparison.discCount.local === null ? 0 : Math.abs(comparison.discCount.local - comparison.discCount.candidate),
            counted ? comparison.files.reduce((sum, file) => sum + Math.abs(file.deltaMs ?? 0), 0) : 0];
    };
    for (let index = 1; index < others.length; index++) {
        const [previous, current] = [sortKey(others[index - 1]), sortKey(others[index])];
        const order = previous[0] - current[0] || previous[1] - current[1] || previous[2] - current[2]
            || (others[index - 1].releaseId < others[index].releaseId ? -1 : 1);
        assert.ok(order < 0, `${others[index - 1].releaseId} before ${others[index].releaseId}`);
    }
    assert.ok(others[0].comparison!.trackCount.candidate === 9, 'the nearest non-matching editions are the 9-track remasters');
    assert.equal(others.at(-1)!.comparison!.trackCount.candidate, 27, 'the 27-track SACD is the farthest');
});

test('a fetched release with another ID is incomplete, and a duplicate key keeps its complete entry in either order', () => {
    const files = filesFrom(hotelBase);
    // The DCC edition's canonical form sorts before the Asylum edition's, so a weight that ignored the
    // ID check would keep the mismatched entry.
    const mismatched: LookupCandidate = { ...candidate(release('e38dc685')), key: `musicbrainz:${hotelBase.releaseId}`, releaseId: hotelBase.releaseId };
    const alone = rankLookupCandidates([mismatched], files);
    assert.equal(alone.candidates[0].status, 'incomplete'); assert.equal(alone.preselection, null);
    for (const duplicate of [mismatched, candidate(hotelBase, false)]) {
        const forward = rankLookupCandidates([duplicate, candidate(hotelBase)], files);
        const backward = rankLookupCandidates([candidate(hotelBase), duplicate], files);
        assert.deepEqual(forward, backward);
        assert.equal(forward.candidates.length, 1); assert.equal(forward.candidates[0].status, 'matching');
        assert.equal(forward.preselection?.candidateKey, `musicbrainz:${hotelBase.releaseId}`);
    }
});

test('a shared catalogue number preselects case-insensitively, and an identifier rule without exactly one matching hit falls through', () => {
    const cd = release('8baecda4'), digital = release('8f032fff'), korean = release('85bc0ffc');
    const input = [candidate(korean), candidate(digital), candidate(cd)];
    const byCatalog = rankLookupCandidates(input, filesFrom(cd, { discs: true, identifiers: { catalogNumber: ' bacd-0001 ' } }));
    assert.equal(byCatalog.preselection?.candidateKey, `musicbrainz:${cd.releaseId}`); assert.equal(byCatalog.preselection?.basis, 'catalogNumber');
    // The release-ID tag names the Korean edition, which does not match, so the barcode decides.
    const fallThrough = rankLookupCandidates(input, filesFrom(cd, { discs: true, identifiers: { releaseId: korean.releaseId, barcode: '4582579942951' } }));
    assert.equal(fallThrough.preselection?.candidateKey, `musicbrainz:${cd.releaseId}`); assert.equal(fallThrough.preselection?.basis, 'barcode');
    const partial = filesFrom(cd, { discs: true }).map((file, index) => index ? file : { ...file, identifiers: { ...file.identifiers, barcode: '4582579942951' } });
    assert.equal(rankLookupCandidates(input, partial).preselection, null, 'an identifier carried by only some files is not shared');
    const twoEditions = rankLookupCandidates(hotelCalifornia.map(value => candidate(value)), filesFrom(hotelBase, { jitter, identifiers: { catalogNumber: '7559-60509-2' } }));
    assert.equal(twoEditions.candidates.filter(entry => entry.status === 'matching'
        && release(entry.releaseId).labels.some(label => label.catalogNumber === '7559-60509-2')).length, 2);
    assert.equal(twoEditions.preselection, null, 'a catalogue number on two matching editions preselects nothing');
});

test('an unverified candidate is never preselected, even by its own release ID', () => {
    const single = structuredClone(release('5302459e'));
    single.media[0].tracks[0].lengthMs = null;
    const ranked = rankLookupCandidates([candidate(single)], [{ slotId: 'only', order: 0, durationMs: 217_000, durationPrecisionMs: 0, discNumber: null,
        trackNumber: null, artistTags: [], identifiers: { ...noIdentifiers, releaseId: single.releaseId } }]);
    assert.equal(ranked.candidates[0].status, 'unverified'); assert.equal(ranked.preselection, null); assert.deepEqual(ranked.groups, []);
});
